  });
});

n8nApi.req("POST", "/rest/workflows", { name: "VyV comparar", nodes: [disparador2, noOp("Se queda", 220), noOp("Se va", 440)], connections: {}, settings: {}, active: false }).then(n8nApi.ok).then((wf) => {
  workflows.push(wf.id);
  const modificado = { ...noOp("Se queda", 220), notes: "cambiado" };
  n8nApi.req("PATCH", `/rest/workflows/${wf.id}`, { versionId: wf.versionId, nodes: [disparador2, modificado, noOp("Nuevo", 660)] }).then(n8nApi.ok).then(
    (w2) => version(wf.id, wf.versionId).then((a) => version(wf.id, w2.versionId).then((b) => {
      const porNombre = (v) => Object.fromEntries(v.nodes.map((n) => [n.name, n]));
      const [na, nb] = [porNombre(a), porNombre(b)];
      const diff = {
        a\u00F1adidos: Object.keys(nb).filter((n) => !na[n]),
        eliminados: Object.keys(na).filter((n) => !nb[n]),
        modificados: Object.keys(nb).filter((n) => na[n] && JSON.stringify(na[n]) !== JSON.stringify(nb[n]))
      };
      cy.evidencia(`Diff: ${JSON.stringify(diff)}`);
      expect(diff).to.deep.eq({ a\u00F1adidos: ["Nuevo"], eliminados: ["Se va"], modificados: ["Se queda"] });
    }))
  );
});

